mapper.select:
select ssr.SEQ_NO, ssr.PORTFOLIO_ID, ssr.SETTLE_DATE, ssr.MARKET_ID FINPROD_ID, ssr.TRADE_MARKET, ssr.CHECK_RESULT, ssr.CUSTOMER_ID, ssr.STL_SEC_DEME, ssrd.FINPROD_TYPE, IFNULL(ssrd.COMMISSION_AMT, 0) COMMISSION_AMT, IFNULL(ssrd.JSF_AMT, 0) JSF_AMT, IFNULL(ssrd.ZGF_AMT, 0) ZGF_AMT, IFNULL(ssrd.STAMP_FEE, 0) STAMP_FEE, IFNULL(ssrd.SETTLE_FEE, 0) SETTLE_FEE, IFNULL(ssrd.GHF_AMT, 0) GHF_AMT, IFNULL(ssrd.SXF_AMT, 0) SXF_AMT, IFNULL(ssrd.TRADE_AMT, 0) TRADE_AMT, IFNULL(ssrd.TRADE_NUM, 0) TRADE_NUM, IFNULL(ssr.COMMISSION_AMT, 0) COMMISSION_AMT2, IFNULL(ssr.JSF_AMT, 0) JSF_AMT2, IFNULL(ssr.ZGF_AMT, 0) ZGF_AMT2, IFNULL(ssr.STAMP_FEE, 0) STAMP_FEE2, IFNULL(ssr.SETTLE_FEE, 0) SETTLE_FEE2, IFNULL(ssr.GHF_AMT, 0) GHF_AMT2, IFNULL(ssr.SXF_AMT, 0) SXF_AMT2, IFNULL(ssr.FPRICE_AMT, 0) TRADE_AMT2, IFNULL(ssr.TRADE_NUM, 0) TRADE_NUM2 from STL_SEC_RECON ssr inner join STL_SEC_RECON_DEAL ssrd on ssrd.SEQ_NO = ssr.SEQ_NO /* left join ( select sum(std.COMMISSION_AMT) COMMISSION_AMT, sum(std.JSF_AMT) JSF_AMT, sum(std.ZGF_AMT) ZGF_AMT, sum(std.STAMP_FEE) STAMP_FEE, sum(std.SETTLE_FEE) SETTLE_FEE, sum(std.GHF_AMT) GHF_AMT, sum(std.SXF_AMT) SXF_AMT, sum(std.FPRICE_AMT) FPRICE_AMT, sum(std.SHARE_AMT) TRADE_NUM, detail.SEQ_NO from STL_SEC_RECON_DETAIL detail inner join settle_trans_data std on std.TRADE_ID = detail.TRADE_ID group by detail.SEQ_NO ) aa on aa.SEQ_NO = ssr.SEQ_NO*/ where 1=1
AND ssr.PORTFOLIO_ID IN
null) OR ssr.PORTFOLIO_ID IN (
#{item}
AND ssr.FINPROD_ID like CONCAT_WS('', '%', #{finprodId}, '%')
AND ssr.TRADE_MARKET = #{tradeMarket}
AND ssr.SETTLE_DATE >= STR_TO_DATE(#{tradeDateBegin}, '%Y-%m-%d')
AND ssr.SETTLE_DATE <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
AND ssr.CHECK_RESULT = #{accountStatus}
order by ssr.CUSTOMER_ID, ssr.SETTLE_DATE

with tmp as( select ssrd.SEQ_NO, ssrd.INSTRUCTION_ID, ssrd.PORTFOLIO_ID, ssrd.TRADE_DATE, ssrd.TRADE_ID, ssrd.FINPROD_ID, ssrd.MARKET_ID, ssrd.TRADE_MARKET, ssrd.CUSTOMER_ID, IFNULL(aa.PARA_VALUE, bb.PARA_VALUE) PARA_VALUE, ssrd.FINPROD_TYPE, ssrd.PS, ssrd.SEC_ACCT_ID, ssrd.TERM_TYPE, ssrd.COMMISSION_AMT, ssrd.JSF_AMT, ssrd.ZGF_AMT, ssrd.STAMP_FEE, ssrd.SETTLE_FEE, ssrd.GHF_AMT, ssrd.SXF_AMT, ssrd.TRADE_AMT, ssrd.TRADE_NUM, ssrd.OTHER_FEEAMT from STL_SEC_RECON_DEAL ssrd left join STL_SEC_RECON ssr on ssr.SEQ_NO = ssrd.SEQ_NO left join STL_SEC_RECON_PARA aa on aa.CUSTOMER_ID = ssrd.CUSTOMER_ID and aa.PARA_CODE = #{PARA_CODE_02} left join STL_SEC_RECON_PARA bb on (bb.CUSTOMER_ID = '' or bb.CUSTOMER_ID is null) and bb.PARA_CODE = #{PARA_CODE_02} where (ssr.CHECK_RESULT IS NULL or ssr.CHECK_RESULT = '' or ssr.CHECK_RESULT = #{CHECK_RESULT_0}) and ssrd.TRADE_DATE = STR_TO_DATE(#{sysdate}, '%Y-%m-%d')
AND ssr.PORTFOLIO_ID IN
null) OR ssr.PORTFOLIO_ID IN (
#{item}
AND ssrd.FINPROD_ID like CONCAT_WS('', '%', #{finprodId}, '%')
AND ssrd.SEQ_NO = #{seqNo}
AND ssrd.TRADE_MARKET = #{tradeMarket}
) select a.SEQ_NO, a.INSTRUCTION_ID, a.PORTFOLIO_ID, a.TRADE_DATE, a.TRADE_ID, a.FINPROD_ID, a.MARKET_ID, a.TRADE_MARKET, a.CUSTOMER_ID, a.PARA_VALUE, a.FINPROD_TYPE, a.PS, a.SEC_ACCT_ID, a.TERM_TYPE, a.COMMISSION_AMT, a.JSF_AMT, a.ZGF_AMT, a.STAMP_FEE, a.SETTLE_FEE, a.GHF_AMT, a.SXF_AMT, a.OTHER_FEEAMT, a.TRADE_AMT, a.TRADE_NUM, ss.APPLY_TRADE_ID TRADE_ID2, ss.COMMISSION_AMT2, ss.JSF_AMT2, ss.ZGF_AMT2, ss.STAMP_FEE2, ss.SETTLE_FEE2, ss.GHF_AMT2, ss.SXF_AMT2, ss.FPRICE_AMT2 TRADE_AMT2, ss.SHARE_AMT2 TRADE_NUM2, ss.FINPROD_TYPE2 FINPROD_TYPE2, ss.PS PS2, ss.TRADE_MARKET TRADE_MARKET2, ss.TRADE_DATE TRADE_DATE2, ss.SEC_ACCT_ID SEC_ACCT_ID2 from tmp a inner join ( select std.APPLY_TRADE_ID, SUM(std.COMMISSION_AMT) COMMISSION_AMT2, SUM(std.JSF_AMT) JSF_AMT2, SUM(std.ZGF_AMT) ZGF_AMT2, SUM(std.STAMP_FEE) STAMP_FEE2, SUM(std.SETTLE_FEE) SETTLE_FEE2, SUM(std.GHF_AMT) GHF_AMT2, SUM(std.SXF_AMT) SXF_AMT2, SUM(std.FPRICE_AMT) FPRICE_AMT2, SUM(std.SHARE_AMT) SHARE_AMT2, std.FINPROD_TYPE2, std.PS, std.TRADE_MARKET, std.TRADE_DATE, std.SEC_ACCT_ID from SETTLE_TRANS_DATA std inner join tmp b on b.INSTRUCTION_ID = std.APPLY_TRADE_ID and b.PARA_VALUE = #{PARA_VALUE_02} GROUP BY std.APPLY_TRADE_ID,std.FINPROD_TYPE2,std.PS,std.TRADE_MARKET,std.TRADE_DATE,std.SEC_ACCT_ID ) ss on a.INSTRUCTION_ID = ss.APPLY_TRADE_ID where a.PARA_VALUE = #{PARA_VALUE_02} UNION ALL select b.SEQ_NO, b.INSTRUCTION_ID, b.PORTFOLIO_ID, b.TRADE_DATE, b.TRADE_ID, b.FINPROD_ID, b.MARKET_ID, b.TRADE_MARKET, b.CUSTOMER_ID, b.PARA_VALUE, b.FINPROD_TYPE, b.PS, b.SEC_ACCT_ID, b.TERM_TYPE, b.COMMISSION_AMT, b.JSF_AMT, b.ZGF_AMT, b.STAMP_FEE, b.SETTLE_FEE, b.GHF_AMT, b.SXF_AMT, b.OTHER_FEEAMT, b.TRADE_AMT, b.TRADE_NUM, std.TRADE_ID TRADE_ID2, std.COMMISSION_AMT COMMISSION_AMT2, std.JSF_AMT JSF_AMT2, std.ZGF_AMT ZGF_AMT2, std.STAMP_FEE STAMP_FEE2, std.SETTLE_FEE SETTLE_FEE2, std.GHF_AMT GHF_AMT2, std.SXF_AMT SXF_AMT2, std.FPRICE_AMT TRADE_AMT2, std.SHARE_AMT TRADE_NUM2, std.FINPROD_TYPE2 FINPROD_TYPE2, std.PS PS2, std.TRADE_MARKET TRADE_MARKET2, std.TRADE_DATE TRADE_DATE2, std.SEC_ACCT_ID SEC_ACCT_ID2 from SETTLE_TRANS_DATA std inner join tmp b on b.TRADE_ID = std.TRADE_ID and b.TRADE_ID is not null and b.TRADE_ID != '' and b.PARA_VALUE = #{PARA_VALUE_03} UNION ALL select b.SEQ_NO, b.INSTRUCTION_ID, b.PORTFOLIO_ID, b.TRADE_DATE, b.TRADE_ID, b.FINPROD_ID, b.MARKET_ID, b.TRADE_MARKET, b.CUSTOMER_ID, b.PARA_VALUE, b.FINPROD_TYPE, b.PS, b.SEC_ACCT_ID, b.TERM_TYPE, b.COMMISSION_AMT, b.JSF_AMT, b.ZGF_AMT, b.STAMP_FEE, b.SETTLE_FEE, b.GHF_AMT, b.SXF_AMT, b.OTHER_FEEAMT, b.TRADE_AMT, b.TRADE_NUM, std.TRADE_ID TRADE_ID2, std.COMMISSION_AMT COMMISSION_AMT2, std.JSF_AMT JSF_AMT2, std.ZGF_AMT ZGF_AMT2, std.STAMP_FEE STAMP_FEE2, std.SETTLE_FEE SETTLE_FEE2, std.GHF_AMT GHF_AMT2, std.SXF_AMT SXF_AMT2, std.FPRICE_AMT TRADE_AMT2, std.SHARE_AMT TRADE_NUM2, std.FINPROD_TYPE2 FINPROD_TYPE2, std.PS PS2, std.TRADE_MARKET TRADE_MARKET2, std.TRADE_DATE TRADE_DATE2, std.SEC_ACCT_ID SEC_ACCT_ID2 from SETTLE_TRANS_DATA std inner join tmp b on b.PARA_VALUE = #{PARA_VALUE_03} and std.FINPROD_ID = b.FINPROD_ID and std.PS = b.PS and std.PORTFOLIO_ID = b.PORTFOLIO_ID and std.SEC_ACCT_ID = b.SEC_ACCT_ID and (b.TRADE_ID is null or b.TRADE_ID = '')

select
from settle_trans_data std WHERE 1=1
AND std.TRADE_ID = #{tradeId, jdbcType=VARCHAR}
AND std.APPLY_TRADE_ID = #{applyTradeId, jdbcType=VARCHAR}
order by std.SHARE_AMT desc
